package org.apache.commons.math.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.FieldElement;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Dfp.toDouble()
 */
public class Dfp_toDouble_TriageGen2Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testToDouble_NaN() {
        // Using the constructor that allows setting NaN via bits/sign/nans
        // Based on signature: protected Dfp(final DfpField field, final byte sign, final byte nans)
        // Assuming nans non-zero triggers isNaN()
        Dfp nan = new Dfp(DfpField.dfpField, (byte) 0, (byte) 1);
        assertTrue(Double.isNaN(nan.toDouble()));
    }

    @Test
    public void testToDouble_PositiveInfinity() {
        // Assuming isInfinite() is triggered by specific internal state
        // We use a value that is clearly larger than double max
        Dfp posInf = new Dfp(DfpField.dfpField, new String("1e400"));
        // If the logic handles exponent > 1023
        assertTrue(Double.isInfinite(posInf.toDouble()));
        assertTrue(posInf.toDouble() > 0);
    }

    @Test
    public void testToDouble_NegativeInfinity() {
        Dfp negInf = new Dfp(DfpField.dfpField, new String("-1e400"));
        assertTrue(Double.isInfinite(negInf.toDouble()));
        assertTrue(negInf.toDouble() < 0);
    }

    @Test
    public void testToDouble_Zero() {
        Dfp zero = new Dfp(DfpField.dfpField, new String("0.0"));
        assertEquals(0.0, zero.toDouble(), DELTA);

        Dfp negZero = new Dfp(DfpField.dfpField, new String("-0.0"));
        double res = negZero.toDouble();
        assertEquals(0.0, res, DELTA);
        // Check sign if the implementation supports -0.0
        if (res == 0.0) {
            assertEquals(-0.0, res, 0.0);
        }
    }

    @Test
    public void testToDouble_NormalPositive() {
        Dfp val = new Dfp(DfpField.dfpField, new String("123.456"));
        assertEquals(123.456, val.toDouble(), DELTA);
    }

    @Test
    public void testToDouble_NormalNegative() {
        Dfp val = new Dfp(DfpField.dfpField, new String("-0.000123456"));
        assertEquals(-0.000123456, val.toDouble(), DELTA);
    }

    @Test
    public void testToDouble_SmallUnderflow() {
        // exponent < -1074 returns 0
        Dfp tiny = new Dfp(DfpField.dfpField, new String("1e-400"));
        assertEquals(0.0, tiny.toDouble(), 0.0);
    }

    @Test
    public void testToDouble_Subnormal() {
        // Test values in the subnormal range (exponent around -1022 to -1074)
        Dfp subnormal = new Dfp(DfpField.dfpField, new String("5e-324"));
        double result = subnormal.toDouble();
        assertTrue(result > 0);
        assertTrue(result < 1e-300);
    }

    @Test
    public void testToDouble_RoundingUpToNextPowerOfTwo() {
        // This targets the logic: if (mantissa == 4503599627370496L) { mantissa = 0; exponent++; }
        // We need a Dfp value that, when multiplied by 2^52, results in exactly that constant
        // 4503599627370496 is 2^52.
        // A value slightly less than a power of 2 that rounds up.
        Dfp val = new Dfp(DfpField.dfpField, new String("0.99999999999999999999")); 
        // The exact value depends on Dfp precision, but we want to trigger the 'mantissa = 0' branch
        double result = val.toDouble();
        assertFalse(Double.isNaN(result));
    }

    @Test
    public void testToDouble_LargeExponentThreshold() {
        // Test exponent > 1023
        Dfp huge = new Dfp(DfpField.dfpField, new String("1e308")); // Close to max double
        double res = huge.toDouble();
        assertFalse(Double.isInfinite(res));

        Dfp wayHuge = new Dfp(DfpField.dfpField, new String("1e400"));
        assertTrue(Double.isInfinite(wayHuge.toDouble()));
    }

    @Test
    public void testToDouble_NegativeExponentThreshold() {
        // Test exponent <= -1023 (subnormal logic)
        Dfp verySmall = new Dfp(DfpField.dfpField, new String("1e-310"));
        double res = verySmall.toDouble();
        assertTrue(res > 0);
        assertTrue(res < 1e-300);
    }

    @Test
    public void testToDouble_ExactPowerOfTwo() {
        Dfp pow2 = new Dfp(DfpField.dfpField, new String("1024.0"));
        assertEquals(1024.0, pow2.toDouble(), DELTA);

        Dfp pow2Neg = new Dfp(DfpField.dfpField, new String("-1024.0"));
        assertEquals(-1024.0, pow2Neg.toDouble(), DELTA);
    }
}
